const body = $input.first().json.body || $input.first().json;
const texto = String(body.texto || body.data?.message?.conversation || '').trim();
const upper = texto.toUpperCase();
const stopWords = ['BAJA', 'STOP', 'SALIR', 'NO MAS', 'NO MÁS', 'CANCELAR'];
const esBaja = stopWords.some(w => upper === w || upper.startsWith(w + ' '));
const esEncuesta = /^[1-5]$/.test(texto);
const calificacion = esEncuesta ? Number(texto) : null;
const instance = body.instance || 'olivia-lima-wa';
const rawPhone = String(body.celular || body.data?.key?.remoteJid || '').replace(/\D/g, '').slice(-9);
const numeroWa = rawPhone.length === 9 ? `51${rawPhone}` : rawPhone;

return [{
  json: {
    negocio_id: body.negocio_id || null,
    instance,
    numero_wa: numeroWa,
    celular_e164: numeroWa ? `+${numeroWa}` : '',
    texto,
    es_baja: esBaja,
    es_encuesta: esEncuesta,
    calificacion,
    es_promotor: calificacion !== null && calificacion >= 4
  }
}];
